import React, { useState } from 'react';
import { useEffect, useRef } from 'react';

// Create the MemoryLeakHunt component function here
function MemoryLeakHunt() {
  // Initialize count state here
  const [count, setCount] = useState<number>(0);

  // Initialize isTimerActive state here
  const [isTimerActive, setIsTimerActive] = useState<boolean>(false);

  // Create a ref for interval ID here
  const intervalRef = useRef<NodeJS.Timeout | null>(null);

  // Define the startTimer handler here
  const startTimer = () => {
    if (!isTimerActive) {
      setIsTimerActive(true);
      intervalRef.current = setInterval(() => {
        setCount(prev => prev + 1);
      }, 1000);
    }
  };

  // Define the stopTimer handler here
  const stopTimer = () => {
    if (intervalRef.current) {
      clearInterval(intervalRef.current);
      intervalRef.current = null;
      setIsTimerActive(false);
    }
  };

  // Add useEffect for timer cleanup here
  useEffect(() => {
    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
      }
    };
  }, []);

  return (
    <div className="memory-leak-hunt">
      {/* Add two paragraph elements here to display count and isTimerActive */}
      <p>Count: {count}</p>
      <p>Timer Active: {isTimerActive ? 'Yes' : 'No'}</p>
      {/* Add Start Timer and Stop Timer buttons here */}
    </div>
  );
}

